class FenwickTree:
    """Binary Indexed Tree for logarithmic range prefix sums."""
    def __init__(self, size: int) -> None:
        self.tree = [0] * (size + 1)
    def update(self, i: int, delta: int) -> None:
        while i < len(self.tree):
            self.tree[i] += delta
            i += i & (-i)
    def query(self, i: int) -> int:
        total = 0
        while i > 0:
            total += self.tree[i]
            i -= i & (-i)
        return total

