def compute_kmp_lps(pattern: str) -> list[int]:
    """Compute Longest Prefix Suffix table for Knuth-Morris-Pratt."""
    lps = [0] * len(pattern)
    length = 0
    i = 1
    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length != 0:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    return lps

